WITH scope AS (SELECT ARRAY['public','pos','internal','billing','ai','contract','mcp_private','blog_mcp_private','neon_auth','newhope_auth']::text[] names),
rels AS (SELECT c.oid,n.nspname AS schema,c.relname AS name,c.relkind AS kind,c.relrowsecurity AS rls,c.relforcerowsecurity AS force_rls,pg_get_userbyid(c.relowner) AS owner FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=ANY((SELECT names FROM scope)::text[]) AND c.relkind IN ('r','p','v','m','S')),
counts AS (SELECT r.schema,r.name,r.kind,r.rls,r.force_rls,r.owner, CASE WHEN r.kind IN ('r','p') THEN ((xpath('/row/n/text()',query_to_xml(format('SELECT count(*)::text n FROM %I.%I',r.schema,r.name),false,true,'')))[1]::text)::bigint END AS rows FROM rels r)
SELECT jsonb_build_object(
'capturedAt',now(),'version',current_setting('server_version'),'database',current_database(),
'relations',(SELECT jsonb_agg(to_jsonb(c) ORDER BY schema,name) FROM counts c),
'columns',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'defaultHash',md5(pg_get_expr(d.adbin,d.adrelid))) ORDER BY n.nspname,c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped AND c.relkind IN ('r','p','v','m') AND n.nspname=ANY((SELECT names FROM scope)::text[])),
'constraints',(SELECT jsonb_agg(jsonb_build_object('schema',r.schema,'table',r.name,'name',c.conname,'type',c.contype,'validated',c.convalidated,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY r.schema,r.name,c.conname) FROM pg_constraint c JOIN rels r ON r.oid=c.conrelid),
'indexes',(SELECT jsonb_agg(jsonb_build_object('schema',r.schema,'table',r.name,'name',c.relname,'valid',i.indisvalid,'definition',pg_get_indexdef(c.oid)) ORDER BY r.schema,r.name,c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN rels r ON r.oid=i.indrelid),
'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'hash',md5(pg_get_functiondef(p.oid)),'securityDefiner',p.prosecdef) ORDER BY n.nspname,p.proname,p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=ANY((SELECT names FROM scope)::text[]) AND p.prokind IN ('f','p')),
'triggers',(SELECT jsonb_agg(jsonb_build_object('schema',r.schema,'table',r.name,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY r.schema,r.name,t.tgname) FROM pg_trigger t JOIN rels r ON r.oid=t.tgrelid WHERE NOT t.tgisinternal),
'views',(SELECT jsonb_agg(jsonb_build_object('schema',r.schema,'name',r.name,'hash',md5(pg_get_viewdef(r.oid,true))) ORDER BY r.schema,r.name) FROM rels r WHERE kind IN ('v','m')),
'policies',(SELECT jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'roles',roles,'command',cmd,'hash',md5(coalesce(qual,'')||'|'||coalesce(with_check,''))) ORDER BY schemaname,tablename,policyname) FROM pg_policies WHERE schemaname=ANY((SELECT names FROM scope)::text[])),
'extensions',(SELECT jsonb_agg(jsonb_build_object('name',extname,'version',extversion)) FROM pg_extension),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypassRls',rolbypassrls,'canLogin',rolcanlogin,'inherit',rolinherit)) FROM pg_roles WHERE rolname NOT LIKE 'pg_%'),
'grants',(SELECT jsonb_agg(to_jsonb(g) ORDER BY g.schema,g.grantee,g.privilege) FROM (SELECT table_schema AS schema,grantee,privilege_type AS privilege,count(*)::int AS tables FROM information_schema.table_privileges WHERE table_schema=ANY((SELECT names FROM scope)::text[]) GROUP BY 1,2,3) g)
) AS audit
